/**
 * Seed Places, historical Events, and Stories for the 15 stub towns.
 * Run: npx tsx scripts/seed-stub-towns.ts [--dry-run]
 */

import "dotenv/config";
import { PrismaClient, Prisma } from "@prisma/client";

const prisma = new PrismaClient({ log: ["error"] });
const DRY = process.argv.includes("--dry-run");

// ── Helpers ───────────────────────────────────────────────────────────────────

async function upsertPlace(data: Prisma.PlaceCreateInput) {
  if (DRY) { console.log(`  [place] ${data.name}`); return; }
  await prisma.place.upsert({
    where: { id: data.id as string },
    create: data,
    update: { name: data.name, description: data.description },
  });
}

async function upsertEvent(data: Prisma.EventCreateInput) {
  if (DRY) { console.log(`  [event] ${data.name}`); return; }
  await prisma.event.upsert({
    where: { id: data.id as string },
    create: data,
    update: { name: data.name, summary: data.summary },
  });
}

async function upsertStory(data: Prisma.StoryCreateInput) {
  if (DRY) { console.log(`  [story] ${data.title}`); return; }
  const existing = await prisma.story.findUnique({ where: { slug: data.slug as string } });
  if (existing) return;
  await prisma.story.create({ data });
}

