  await upsertPlace({ id: "place-lebanon-green", name: "Lebanon Green (French Army Encampment Site)", placeType: "LANDMARK", description: "The broad Lebanon Green, one of the longest town greens in New England, served as the encampment site for Rochambeau's French army during its march from Newport to Yorktown in June 1781. An estimated 5,000 French soldiers camped here for several days. The Green retains its 18th-century character and is surrounded by period buildings.", lat: 41.6374, lng: -72.2038, address: "Lebanon Green, Lebanon, CT 06249", hours: "Open daily", admission: "Free", town: { connect: { id } } });
