  await upsertEvent({ id: "event-lebanon-trumbull-governor", name: "Jonathan Trumbull Sides with Patriots", startDate: new Date("1775-07-01"), datePrecision: "MONTH", summary: "Trumbull's decision made Connecticut the only colony whose sitting royal-era governor backed the Revolution, providing continuity of government and administrative capacity that proved essential.", verificationStatus: "VERIFIED", significanceWeight: 90, town: { connect: { id } } });
  await upsertEvent({ id: "event-lebanon-french-army-march", name: "Rochambeau's Army Camps on Lebanon Green", startDate: new Date("1781-06-18"), datePrecision: "DAY", summary: "The French army's transit through Connecticut demonstrated Trumbull's logistical achievement — he had organized a supply network capable of feeding and equipping a foreign army on the move.", verificationStatus: "VERIFIED", significanceWeight: 80, town: { connect: { id } } });
  await upsertEvent({ id: "event-lebanon-washington-visit", name: "Washington Meets Trumbull in Lebanon", startDate: new Date("1775-10-18"), datePrecision: "MONTH", summary: "Washington's reliance on Trumbull demonstrated the personal networks that kept the Continental Army operational when Congress and the commissary system repeatedly failed.", verificationStatus: "VERIFIED", significanceWeight: 70, town: { connect: { id } } });

  await upsertStory({ id: "story-lebanon-brother-jonathan", slug: "story-lebanon-brother-jonathan", title: "Brother Jonathan: The Governor Who Kept the Army Alive", storyType: "HISTORICAL_VOICE", textVersion: "Washington called him 'Brother Jonathan.' The nickname stuck and eventually became slang for Connecticut itself — and then for America. Jonathan Trumbull Sr. was the only royal governor to side with the Patriots, and he did it at considerable personal cost. His mercantile business collapsed under the weight of wartime requisitions. He gave more than he charged. He requisitioned cattle, blankets, shoes, and powder from Connecticut farmers and merchants, promising payment that came slowly if at all. His ledgers from the Lebanon War Office record thousands of transactions — a monument to the unglamorous arithmetic of keeping an army in the field.", verificationStatus: "ORAL_TRADITION", town: { connect: { id } } });
