  await upsertPlace({ id: "place-vincennes-indiana-territory-capitol", name: "Indiana Territory Capitol", placeType: "GOVERNMENT", description: "Vincennes served as the first capital of the Indiana Territory after the Northwest Ordinance of 1787, which was directly enabled by Clark's 1779 military campaign. The territorial capitol building, reconstructed on its original site, marks Vincennes's transition from contested frontier outpost to seat of American civil government — a transformation that began the night Clark's men crossed the flooded Wabash.", lat: 38.6745, lng: -87.5254, address: "Harrison St, Vincennes, IN 47591", hours: "Mon–Sat 9am–5pm", admission: "Free", town: { connect: { id } } });
  await upsertPlace({ id: "place-vincennes-wabash-river-crossing", name: "Wabash River Crossing Site", placeType: "LANDMARK", description: "In February 1779, George Rogers Clark's force spent five days crossing the flooded Wabash River bottomlands in chest-deep icy water to reach Vincennes. The crossing point — approximately where the river bends near the memorial — became legendary. Clark kept morale alive by having the drummers march at the front, beating cadence while soldiers waded. No account explains why they didn't turn back.", lat: 38.6780, lng: -87.5320, address: "Wabash River, Vincennes, IN", hours: "Open daily", admission: "Free", town: { connect: { id } } });

  await upsertEvent({ id: "event-vincennes-clark-wabash-crossing", name: "Clark's Army Crosses the Wabash in Winter", startDate: new Date("1779-02-13"), datePrecision: "DAY", summary: "One of the most audacious military movements of the Revolution — 172 men in chest-deep floodwater for five days — succeeded because Clark understood that Hamilton would not expect an attack in February.", verificationStatus: "VERIFIED", significanceWeight: 100, town: { connect: { id } } });
  await upsertEvent({ id: "event-vincennes-hamilton-surrender", name: "Lieutenant Governor Hamilton Surrenders Fort Sackville", startDate: new Date("1779-02-25"), datePrecision: "DAY", summary: "The capture of 'the Hair-Buyer' Hamilton — so called for his policy of paying Indigenous allies for American scalps — was a propaganda coup as well as a military one. It also established American sovereignty over the entire Northwest.", verificationStatus: "VERIFIED", significanceWeight: 100, town: { connect: { id } } });
