async function main() {
  console.log(`Mode: ${DRY ? "DRY RUN" : "LIVE"}\n`);

  const seeders: Array<[string, () => Promise<void>]> = [
    ["CT Lebanon", seedLebanon],
    ["IN Vincennes", seedVincennes],
    ["MA Quincy", seedQuincy],
    ["MA Acton", seedActon],
    ["MA Lincoln", seedLincoln],
    ["MA Bedford", seedBedford],
    ["ME Machias", seedMachias],
    ["NC Edenton", seedEdenton],
    ["NC Halifax", seedHalifax],
    ["NH New Castle", seedNewCastle],
    ["NY Oriskany", seedOriskany],
    ["PA Chadds Ford", seedChadds],
    ["RI Portsmouth", seedPortsmouth],
    ["RI Warwick", seedWarwick],
    ["VT Hubbardton", seedHubbardton],
  ];

  for (const [name, seeder] of seeders) {
    console.log(`\n── ${name} ──`);
    try {
      await seeder();
      console.log(`  ✓ done`);
    } catch (e) {
      console.error(`  ✗ error: ${String(e).slice(0, 120)}`);
    }
  }

  console.log("\n✅ Stub towns seeded.");
}

main()
  .catch((e) => { console.error(e); process.exit(1); })
  .finally(() => prisma.$disconnect());
